// Example: decode a typed assistant response into a Go struct using the generic helper
package main

import (
  "context"
  "fmt"
  "github.com/redwood-inference/go-sdk/decoder"
)

type IntentResponse struct {
  Intent string `json:"intent"`
  Score  float64 `json:"score"`
}

func main() {
  raw := []byte(`{\"intent\":\"purchase\",\"score\":0.92}`)
  var r IntentResponse
  if err := decoder.Decode[IntentResponse](raw, &r); err != nil {
    panic(err)
  }
  fmt.Println(r.Intent, r.Score)
}
// Example: streaming assistant decoder with retry
package examples

import (
  "context"
  "fmt"
  "time"
  rsdk "github.com/redwood-inference/go-sdk/client"
  dec "github.com/redwood-inference/go-sdk/decoder"
)

func StreamChat(ctx context.Context, client *rsdk.Client, req rsdk.ChatRequest) error {
  // StreamDecoder yields typed ChatDelta objects as they arrive
  stream, errs := dec.StreamDecode[ChatDelta](ctx, func(w dec.Emitter) error {
    // transport hook: call client.StreamChat and forward raw bytes into Emitter
    return client.StreamChat(req, w)
  })

  // Wrap with retry helper that will re-open the stream on transient errors
  streamWithRetry := dec.StreamWithRetry(ctx, stream, errs, dec.RetryOptions{
    MaxAttempts: 3,
    Backoff:     dec.ExponentialBackoff(200*time.Millisecond),
    ResumeMode:  dec.ResumeWhenAvailable,
  })

  for delta := range streamWithRetry {
    fmt.Printf("token: %s\n", delta.Content)
  }
  if err := <-errs; err != nil {
    return err
  }
  return nil
}
// Note: ChatDelta is a typed struct representing partial stream chunks. StreamWithRetry handles resume tokens when available; otherwise it will re-request and callers should be idempotent when merging partial results.
